	@Test
	void lmdbObjectiveRejectsCandidatesBeyondMaterializationBudget() throws Exception {
		PackedCostEstimate materialized = new PackedCostEstimate();
		materialized.setRows(10.0d, 10.0d);
		materialized.setLocalPhysicalCost(10.0d, 0.0d, 1.0d, 0.0d, 10.0d, 100.0d, 0.0d, 0.0d, 10.0d);
		PackedCostEstimate streaming = new PackedCostEstimate();
		streaming.setRows(10.0d, 10.0d);
		streaming.setLocalPhysicalCost(1_000.0d, 100.0d, 100.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);

		var scorer = LmdbFrontierPackedCostSession.class.getDeclaredMethod(
				"normalizedObjectiveScore", PackedCostEstimate.class, long.class);
		scorer.setAccessible(true);
		assertEquals(Double.MAX_VALUE, scorer.invoke(null, materialized, 5L));
		assertEquals(streaming.workRows(), scorer.invoke(null, streaming, 5L));
	}

