	@Test
	void heterogeneousUnionStateRemainsExactThroughOptionalAndNotExists(@TempDir Path dataDirectory) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
				.setFrontierSynopsisBudgetBytes(SYNOPSIS_BUDGET_BYTES);
		LmdbStore store = new LmdbStore(dataDirectory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			IRI q = repository.getValueFactory().createIRI("urn:frontier:heterogeneous-pipeline-q");
			IRI optional = repository.getValueFactory().createIRI("urn:frontier:heterogeneous-pipeline-optional");
			IRI blocked = repository.getValueFactory().createIRI("urn:frontier:heterogeneous-pipeline-blocked");
			try (var connection = repository.getConnection()) {
				var values = connection.getValueFactory();
				IRI first = values.createIRI("urn:frontier:heterogeneous-pipeline-subject-1");
				IRI second = values.createIRI("urn:frontier:heterogeneous-pipeline-subject-2");
				IRI third = values.createIRI("urn:frontier:heterogeneous-pipeline-subject-3");
				connection.add(first, PREDICATE,
						values.createIRI("urn:frontier:heterogeneous-pipeline-left-1"));
				connection.add(second, PREDICATE,
						values.createIRI("urn:frontier:heterogeneous-pipeline-left-2"));
				connection.add(third, q,
						values.createIRI("urn:frontier:heterogeneous-pipeline-right-1"));
				connection.add(first, optional,
						values.createIRI("urn:frontier:heterogeneous-pipeline-optional-1"));
				connection.add(third, optional,
						values.createIRI("urn:frontier:heterogeneous-pipeline-optional-3"));
				connection.add(second, blocked,
						values.createIRI("urn:frontier:heterogeneous-pipeline-blocked-value"));
			}
			assertEquals(FrontierSynopsisStatus.READY, store.rebuildFrontierSynopsis());
			String query = """
					SELECT ?subject ?leftValue ?rightValue ?optionalValue
					WHERE {
					  {
					    { ?subject <urn:frontier:p> ?leftValue }
					    UNION
					    { ?subject <urn:frontier:heterogeneous-pipeline-q> ?rightValue }
					  }
					  OPTIONAL {
					    ?subject <urn:frontier:heterogeneous-pipeline-optional> ?optionalValue
					  }
					  FILTER NOT EXISTS {
					    ?subject <urn:frontier:heterogeneous-pipeline-blocked> ?blockedValue
					  }
					}
					""";

			try (var connection = repository.getConnection()) {
				Explanation explanation = connection.prepareTupleQuery(query)
						.explain(Explanation.Level.Optimized);
				Union union = findUnion((TupleExpr) explanation.tupleExpr());
				LeftJoin leftJoin = findLeftJoin((TupleExpr) explanation.tupleExpr());
				Filter filter = findFilter((TupleExpr) explanation.tupleExpr());
				assertNotNull(union, explanation::toString);
				assertNotNull(leftJoin, explanation::toString);
				assertNotNull(filter, explanation::toString);
				assertEquals("lmdb-frontier", union.getStringMetricPlanned(
						TelemetryMetricNames.PLANNED_ESTIMATE_SOURCE), explanation::toString);
				assertEquals("lmdb-frontier", leftJoin.getStringMetricPlanned(
						TelemetryMetricNames.PLANNED_ESTIMATE_SOURCE), explanation::toString);
				assertEquals("lmdb-frontier", filter.getStringMetricPlanned(
						TelemetryMetricNames.PLANNED_ESTIMATE_SOURCE), explanation::toString);
				assertEquals("database_exact", union.getStringMetricPlanned("plannedFrontierGuarantee"),
						explanation::toString);
				assertEquals("database_exact", leftJoin.getStringMetricPlanned("plannedFrontierGuarantee"),
						explanation::toString);
				assertEquals("database_exact", filter.getStringMetricPlanned("plannedFrontierGuarantee"),
						explanation::toString);
				assertEquals(3.0d, union.getDoubleMetricPlanned("plannedFrontierRows"),
						explanation::toString);
				assertEquals(3.0d, leftJoin.getDoubleMetricPlanned("plannedFrontierRows"),
						explanation::toString);
				assertEquals(2.0d, filter.getDoubleMetricPlanned("plannedFrontierRows"),
						explanation::toString);
				assertEquals(2, QueryResults.asList(connection.prepareTupleQuery(query).evaluate()).size());
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void sampledUnionAppliesLeoAfterRawFrontierTransform(@TempDir Path dataDirectory) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
				.setFrontierSynopsisBudgetBytes(16L * 1024L);
		LmdbStore store = new LmdbStore(dataDirectory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			IRI q = repository.getValueFactory().createIRI("urn:frontier:leo-union-q");
			try (var connection = repository.getConnection()) {
				var values = connection.getValueFactory();
				for (int index = 0; index < 2_100; index++) {
					var subject = values.createIRI("urn:frontier:leo-union-subject-" + index);
					connection.add(subject, PREDICATE, values.createIRI("urn:frontier:leo-union-p-" + index));
					connection.add(subject, q, values.createIRI("urn:frontier:leo-union-q-" + index));
				}
			}
			assertEquals(FrontierSynopsisStatus.READY, store.rebuildFrontierSynopsis());
			String query = """
					SELECT ?subject ?leftValue ?rightValue
					WHERE {
					  { ?subject <urn:frontier:p> ?leftValue }
					  UNION
					  { ?subject <urn:frontier:leo-union-q> ?rightValue }
					}
					""";

			Union observed;
			double rawRows;
			try (var connection = repository.getConnection()) {
				Explanation explanation = connection.prepareTupleQuery(query)
						.explain(Explanation.Level.Optimized);
				observed = findUnion((TupleExpr) explanation.tupleExpr());
				assertNotNull(observed, explanation::toString);
				assertEquals("measure_unbiased",
						observed.getStringMetricPlanned("plannedFrontierGuarantee"), explanation::toString);
				rawRows = observed.getDoubleMetricPlanned("plannedFrontierRows");
				assertTrue(rawRows > 0.0d, explanation::toString);
			}

			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			long learnedRows = Math.max(1L, Math.round(rawRows * 4.0d));
			for (int observation = 0; observation < 4; observation++) {
				Union completed = observed.clone();
				completeLeoOperator(completed, learnedRows, rawRows, rawRows, learnedRows);
				statistics.estimatorRuntime().feedback().recordOperatorOutcome(completed);
			}
			assertNotNull(statistics.estimatorRuntime()
					.operatorFeedback(
							observed, rawRows / 2.0d, rawRows / 2.0d, rawRows, rawRows, null));

			try (var connection = repository.getConnection()) {
				Explanation explanation = connection.prepareTupleQuery(query)
						.explain(Explanation.Level.Optimized);
				Union calibrated = findUnion((TupleExpr) explanation.tupleExpr());
				assertNotNull(calibrated, explanation::toString);
				assertEquals("lmdb-frontier+leo", calibrated.getStringMetricPlanned(
						TelemetryMetricNames.PLANNED_ESTIMATE_SOURCE), explanation::toString);
				assertEquals("learned_calibrated",
						calibrated.getStringMetricPlanned("plannedFrontierGuarantee"), explanation::toString);
				assertEquals(rawRows, calibrated.getDoubleMetricPlanned("plannedFrontierRawRows"), 0.0001d,
						explanation::toString);
				assertTrue(calibrated.getDoubleMetricPlanned("plannedFrontierRows") > rawRows,
						explanation::toString);
				assertEquals(4_200, QueryResults.asList(connection.prepareTupleQuery(query).evaluate()).size());
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void heterogeneousUnionRejectsNonComposableLeoBranchBeforeAlignment(@TempDir Path dataDirectory) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
				.setFrontierSynopsisBudgetBytes(16L * 1024L);
		LmdbStore store = new LmdbStore(dataDirectory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			IRI q = repository.getValueFactory().createIRI("urn:frontier:non-composable-union-q");
			IRI r = repository.getValueFactory().createIRI("urn:frontier:non-composable-union-r");
			try (var connection = repository.getConnection()) {
				var values = connection.getValueFactory();
				for (int index = 0; index < 128; index++) {
					var subject = values.createIRI("urn:frontier:non-composable-union-subject-" + index);
					connection.add(subject, PREDICATE,
							values.createIRI("urn:frontier:non-composable-union-p-" + index));
					connection.add(subject, q,
							values.createIRI("urn:frontier:non-composable-union-q-" + index));
					connection.add(subject, r,
							values.createIRI("urn:frontier:non-composable-union-r-" + index));
				}
			}
			assertEquals(FrontierSynopsisStatus.READY, store.rebuildFrontierSynopsis());
			String query = """
					SELECT ?subject ?leftValue ?middleValue ?rightValue
					WHERE {
					  { ?subject <urn:frontier:p> ?leftValue }
					  UNION
					  {
					    ?subject <urn:frontier:non-composable-union-q> ?middleValue .
					    ?subject <urn:frontier:non-composable-union-r> ?rightValue
					  }
					}
					""";

			Join observedBranch;
			double plannedRows;
			double plannedWorkRows;
			try (var connection = repository.getConnection()) {
				Explanation explanation = connection.prepareTupleQuery(query)
						.explain(Explanation.Level.Optimized);
				Union union = findUnion((TupleExpr) explanation.tupleExpr());
				assertNotNull(union, explanation::toString);
				observedBranch = findJoin(union.getRightArg());
				assertNotNull(observedBranch, explanation::toString);
				assertEquals("measure_unbiased",
						observedBranch.getStringMetricPlanned("plannedFrontierGuarantee"), explanation::toString);
				plannedRows = observedBranch.getResultSizeEstimate();
				plannedWorkRows = observedBranch.getCostEstimate();
				assertTrue(plannedRows > 0.0d, explanation::toString);
			}

			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			for (int observation = 0; observation < 4; observation++) {
				Join completed = observedBranch.clone();
				completeLeoOperator(completed, 0L, plannedRows, plannedWorkRows, plannedWorkRows);
				statistics.estimatorRuntime().feedback().recordOperatorOutcome(completed);
			}

			try (var connection = repository.getConnection()) {
				Explanation explanation = assertDoesNotThrow(() -> connection.prepareTupleQuery(query)
						.explain(Explanation.Level.Optimized));
				Union union = findUnion((TupleExpr) explanation.tupleExpr());
				assertNotNull(union, explanation::toString);
				assertTrue(Set.of("ready", "degraded")
						.contains(union.getStringMetricPlanned("plannedFrontierStatus")), explanation::toString);
				assertTrue(union.getResultSizeEstimate() > 0.0d,
						"UNION must retain positive mass from a composable alternative or scalar fallback");
				assertEquals(256, QueryResults.asList(connection.prepareTupleQuery(query).evaluate()).size());
			}
		} finally {
			repository.shutDown();
		}
	}

